    function setManualReview(id,updates,save=false){const current=manualReviews.get(id)||{status:'not-tested',notes:''};manualReviews.set(id,{...current,...updates});saveState.textContent='Unsaved changes';renderSummary(latest);if(save){renderManualChecks();void persistReview();}}
    function renderManualStatusFilters(){manualStatusFilters.replaceChildren();[['all','All'],['not-tested','Not tested'],['pass','Pass'],['needs-attention','Needs attention'],['not-applicable','N/A']].forEach(([value,label])=>{const button=el('button','filter',label);button.type='button';button.setAttribute('aria-pressed',String(activeManualStatus===value));button.addEventListener('click',()=>{activeManualStatus=value;selectedManualId=null;renderManualChecks();});manualStatusFilters.append(button);});}
    function renderManualDetail(check){detail.replaceChildren();if(!check){detail.append(el('div','empty','No manual tasks match this status filter.'));return;}const review=manualReview(check);const header=el('header','detail-header');const kicker=el('div','detail-kicker');kicker.append(el('span','manual-status '+review.status,manualStatusLabel(review.status)));kicker.append(el('span','wcag-level-badge',check.wcagLevel));kicker.append(el('span','detail-kicker-text',check.category+' · Human verification required'));header.append(kicker);header.append(el('h3','',check.title));detail.append(header);const overview=titledSection('What to verify');overview.append(el('p','section-copy',check.description));detail.append(overview);const stepsSection=titledSection('Manual test steps');const steps=el('ol','manual-steps');check.steps.forEach(step=>steps.append(el('li','',step)));stepsSection.append(steps);detail.append(stepsSection);const outcome=titledSection('Review outcome');outcome.append(el('p','section-copy','Choose the result that reflects the evidence from this manual test. Status changes are saved locally.'));const choices=el('div','manual-outcomes');[['not-tested','Not tested'],['pass','Pass'],['needs-attention','Needs attention'],['not-applicable','Not applicable']].forEach(([value,label])=>{const choice=el('button','manual-outcome',label);choice.type='button';choice.setAttribute('aria-pressed',String(review.status===value));choice.addEventListener('click',()=>setManualReview(check.id,{status:value},true));choices.append(choice);});outcome.append(choices);const note=el('label','manual-task-note');note.append(el('span','','Evidence and reviewer notes'));const textarea=el('textarea','');textarea.rows=5;textarea.maxLength=4000;textarea.placeholder='Record what was tested, the result, assistive technology used, and any follow-up needed.';textarea.value=review.notes;textarea.addEventListener('input',()=>setManualReview(check.id,{notes:textarea.value}));note.append(textarea);note.append(el('small','manual-review-help','Use Save review above to store note changes in this local run and include them in exported reports.'));outcome.append(note);detail.append(outcome);const requirements=titledSection('WCAG 2.2 requirements — W3C');const links=el('div','wcag-list');check.wcag.forEach(item=>links.append(externalLink('WCAG '+item,wcagUnderstandingUrls[item]||wcagUnderstandingIndex,'wcag-chip')));requirements.append(links);detail.append(requirements);detail.scrollTop=0;}
    function renderManualChecks(){list.replaceChildren();const checks=latest.manualChecks||[];const counts=manualCounts();queueHeading.textContent='Manual review';filterGroups.hidden=true;manualStatusFilters.hidden=false;renderManualStatusFilters();queueCount.textContent=counts.pass+' pass · '+counts['needs-attention']+' need attention · '+counts['not-tested']+' not tested';const visible=checks.filter(check=>activeManualStatus==='all'||manualReview(check).status===activeManualStatus);if(!checks.length){list.append(el('div','empty','No manual checklist was included in this result.'));renderManualDetail(null);return;}if(!visible.some(check=>check.id===selectedManualId))selectedManualId=visible[0]?.id||null;visible.forEach(check=>{const review=manualReview(check);const row=el('div','manual-nav');const item=el('button','');item.type='button';item.setAttribute('aria-current',String(check.id===selectedManualId));item.append(el('span','manual-status '+review.status,manualStatusLabel(review.status)));item.append(el('span','finding-nav-title',check.title));item.append(el('span','finding-nav-meta',check.category+' · WCAG '+check.wcagLevel+(review.notes?' · Notes recorded':'')));item.addEventListener('click',()=>{selectedManualId=check.id;renderManualChecks();});row.append(item);list.append(row);});renderManualDetail(visible.find(check=>check.id===selectedManualId));}
    function setReviewMode(mode){reviewMode=mode;automatedTab.setAttribute('aria-pressed',String(mode==='automated'));manualTab.setAttribute('aria-pressed',String(mode==='manual'));manualStatusFilters.hidden=mode!=='manual';renderFindings();}
