    const renderDetailWithoutLevelBadges=renderDetail;renderDetail=function(f){renderDetailWithoutLevelBadges(f);detail.scrollTop=0;const severityBadge=detail.querySelector('.detail-kicker .badge');const levelBadge=findingLevelBadge(f);if(severityBadge&&levelBadge)severityBadge.after(levelBadge);let anchor=levelBadge||severityBadge;recurringBadges(f).forEach(badge=>{if(anchor){anchor.after(badge);anchor=badge;}});};
    function findingNav(f){const item=el('button','finding-nav');item.type='button';item.setAttribute('aria-current',String(!selectedGroupId&&f.fingerprint===selectedFingerprint));const meta=el('div','');meta.append(el('span','badge '+f.severity,f.severity));const level=findingLevelBadge(f);if(level)meta.append(level);const historyBadge=historyStatusBadge(f);if(historyBadge)meta.append(historyBadge);recurringBadges(f).forEach(badge=>meta.append(badge));const title=el('span','finding-nav-title');appendTechnicalText(title,f.title);meta.append(title);meta.append(el('span','finding-nav-meta',(f.location.interactionState?'After opening '+f.location.interactionState+' · ':'')+(f.location.selector||f.location.file||f.location.url||f.ruleId)));item.append(meta);item.addEventListener('click',()=>{selectedGroupId=null;selectedFingerprint=f.fingerprint;renderFindings();detail.scrollIntoView({behavior:'smooth',block:'start'});});return item;}
