    function componentGroupNav(group,members){const wrapper=el('section','component-group');const pages=groupPages(group,members);const parent=el('button','component-group-nav');parent.type='button';parent.setAttribute('aria-current',String(group.id===selectedGroupId));const badges=el('span','component-group-badges');badges.append(groupBadge('component-badge',group.category));badges.append(groupBadge('group-count-badge',members.length+' FINDINGS'));badges.append(groupBadge('page-count-badge',pages.length+' PAGE'+(pages.length===1?'':'S')));const newCount=members.filter(f=>currentComparison?.statuses?.[f.fingerprint]==='new').length;if(newCount)badges.append(groupBadge('history-status-badge new',newCount+' NEW'));parent.append(badges);parent.append(el('strong','component-group-title',group.name));parent.append(el('span','component-group-help',(group.kind==='pattern'?'Shared remediation theme across ':'Shared owning component containing ')+members.length+' findings'));parent.addEventListener('click',()=>{selectedGroupId=group.id;selectedFingerprint=null;renderFindings();detail.scrollIntoView({behavior:'smooth',block:'start'});});wrapper.append(parent);return wrapper;}
    renderFindings=function(){if(reviewMode==='manual'){renderManualChecks();return;}queueHeading.textContent='Finding list';filterGroups.hidden=false;list.replaceChildren();const filteredFindings=latest.findings.filter(f=>(activeLevel==='all'||f.wcagLevel===activeLevel)&&(activeFilter==='all'||f.severity===activeFilter));const groups=(latest.findingGroups||[]).map(group=>({group,members:groupMembers(group,latest.findings)})).filter(entry=>entry.members.length>1);const componentGroups=groups.filter(entry=>entry.group.kind!=='pattern');const patternGroups=groups.filter(entry=>entry.group.kind==='pattern');const groupedFingerprints=new Set(groups.flatMap(entry=>entry.members.map(f=>f.fingerprint)));const individualFindings=filteredFindings.filter(f=>!groupedFingerprints.has(f.fingerprint));if(!groups.length&&!individualFindings.length){let message='No findings match this filter.';if(activeFilter==='all'&&activeLevel==='all'&&(latest.metadata.incomplete||[]).length)message='No completed findings are available because one or more pages failed to scan. Review the incomplete-page details above.';else if(activeFilter==='all'&&activeLevel==='all'&&latest.metadata.pagesOrFilesScanned>0)message='The completed page scan produced zero automated axe-core findings. This does not mean the page is fully accessible; continue with manual testing.';list.append(el('div','empty',message));renderDetail(null);return;}if(selectedGroupId&&!groups.some(entry=>entry.group.id===selectedGroupId))selectedGroupId=null;if(selectedFingerprint&&!individualFindings.some(f=>f.fingerprint===selectedFingerprint))selectedFingerprint=null;if(!selectedGroupId&&!selectedFingerprint){if(groups.length)selectedGroupId=groups[0].group.id;else selectedFingerprint=individualFindings[0].fingerprint;}const addGroupSection=(label,entries,className)=>{if(!entries.length)return;const section=el('section','sidebar-section '+className);section.append(el('h4','sidebar-section-label',label));const items=el('div','sidebar-section-items');entries.forEach(entry=>items.append(componentGroupNav(entry.group,entry.members)));section.append(items);list.append(section);};addGroupSection('Components',componentGroups,'sidebar-components');addGroupSection('Issue patterns',patternGroups,'sidebar-patterns');if(individualFindings.length){const findingSection=el('section','sidebar-section sidebar-findings');findingSection.append(el('h4','sidebar-section-label','Individual findings'));const findingItems=el('div','sidebar-section-items');individualFindings.forEach(finding=>findingItems.append(findingNav(finding)));findingSection.append(findingItems);list.append(findingSection);}else if(groups.length){const emptySection=el('section','sidebar-section sidebar-findings');emptySection.append(el('h4','sidebar-section-label','Individual findings'));emptySection.append(el('p','queue-count','Every finding is included in a component or issue-pattern group above.'));list.append(emptySection);}queueCount.textContent=componentGroups.length+' component'+(componentGroups.length===1?'':'s')+' · '+patternGroups.length+' pattern'+(patternGroups.length===1?'':'s')+' · '+individualFindings.length+' individual';const selectedGroup=groups.find(entry=>entry.group.id===selectedGroupId);if(selectedGroup)renderGroupDetail(selectedGroup.group,selectedGroup.members);else renderDetail(individualFindings.find(f=>f.fingerprint===selectedFingerprint)||individualFindings[0]);};
    function setScanControlsExpanded(expanded){document.body.classList.toggle('scan-collapsed',!expanded);scanToggle.setAttribute('aria-expanded',String(expanded));scanToggle.textContent=expanded?'Hide scan controls':'Show scan controls';}
    function setResultSummaryExpanded(expanded){results.classList.toggle('summary-collapsed',!expanded);summaryToggle.setAttribute('aria-expanded',String(expanded));summaryToggle.textContent=expanded?'Hide summary':'Show summary';}
    function setHistoryState(history){currentRunId=history?.run?.id||null;currentComparison=history?.comparison||null;historyRuns=history?.runs||[];manualReviews.clear();Object.entries(history?.run?.review?.manualTasks||{}).forEach(([id,review])=>manualReviews.set(id,review));runReview.hidden=!currentRunId;runNotes.value=history?.run?.review?.notes||'';saveState.textContent='';if(currentRunId){document.getElementById('json-download').href='/api/history/'+currentRunId+'/report.json';document.getElementById('html-download').href='/api/history/'+currentRunId+'/report.html';}else{document.getElementById('json-download').href='/api/report.json';document.getElementById('html-download').href='/api/report.html';}comparisonBase.replaceChildren();const interactionMode=Boolean(history?.run?.result?.metadata?.interactionStatesRequested);const previous=historyRuns.filter(run=>run.id!==currentRunId&&run.completedAt<(history?.run?.result?.metadata?.completedAt||'')&&Boolean(run.interactionStatesRequested)===interactionMode);if(!previous.length){const option=el('option','','No earlier saved run with matching scan settings');option.value='';comparisonBase.append(option);comparisonBase.disabled=true;}else{comparisonBase.disabled=false;previous.forEach(run=>{const option=el('option','',new Date(run.completedAt).toLocaleString()+' · '+run.findings+' findings');option.value=run.id;option.selected=run.id===currentComparison?.baseRunId;comparisonBase.append(option);});}}
    async function persistReview(){if(!currentRunId)return;saveReview.disabled=true;saveState.textContent='Saving…';try{const response=await fetch('/api/history/'+currentRunId+'/review',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({manualTasks:Object.fromEntries(manualReviews),notes:runNotes.value})});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Review could not be saved.');manualReviews.clear();Object.entries(payload.review.manualTasks||{}).forEach(([id,review])=>manualReviews.set(id,review));if(latest?.history?.run)latest.history.run.review=payload.review;saveState.textContent='Saved locally';renderSummary(latest);if(reviewMode==='manual')renderManualChecks();}catch(error){saveState.textContent=error.message;}finally{saveReview.disabled=false;}}
    async function changeComparison(){if(!currentRunId||!comparisonBase.value)return;comparisonBase.disabled=true;try{const response=await fetch('/api/history/'+currentRunId+'/compare?base='+encodeURIComponent(comparisonBase.value));const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Comparison could not be loaded.');currentComparison=payload.comparison;if(latest?.history)latest.history.comparison=currentComparison;renderSummary(latest);renderFindings();setHistoryState(latest.history);}catch(error){status.className='status error';status.textContent=error.message;}finally{comparisonBase.disabled=false;}}
    function historyRow(run){const row=el('article','history-row');const completedLabel=new Date(run.completedAt).toLocaleString();const identity=el('div','');identity.append(el('strong','',completedLabel));identity.append(el('span','',run.target));row.append(identity);const findings=el('div','');findings.append(el('strong','',String(run.findings)));findings.append(el('span','','findings'));row.append(findings);const pages=el('div','');pages.append(el('strong','',String(run.pagesScanned)));pages.append(el('span','','pages'));row.append(pages);const manual=el('div','');manual.append(el('strong','',run.manualCompleted+'/'+run.manualTotal));manual.append(el('span','','manual'));row.append(manual);const actions=el('div','history-row-actions');const open=el('button','secondary','Open run');open.type='button';open.setAttribute('aria-label','Open scan from '+completedLabel+' for '+run.target);open.addEventListener('click',()=>void openHistoryRun(run.id));const remove=el('button','secondary delete-run','Delete');remove.type='button';remove.setAttribute('aria-label','Delete scan from '+completedLabel+' for '+run.target);remove.addEventListener('click',()=>void removeHistoryRun(run));actions.append(open,remove);row.append(actions);return row;}
    function renderHistoryList(runs){historyList.replaceChildren();if(!runs.length){historyList.append(el('div','history-empty','No saved scans yet. Run a website scan to create the first local record.'));return;}const groups=new Map();runs.forEach(run=>{const values=groups.get(run.targetKey)||[];values.push(run);groups.set(run.targetKey,values);});groups.forEach((values,key)=>{const section=el('section','history-group');section.append(el('h3','',key));values.forEach(run=>section.append(historyRow(run)));historyList.append(section);});}
    async function loadHistory(){historyList.replaceChildren(el('div','history-empty','Loading saved runs…'));try{const response=await fetch('/api/history');const payload=await response.json();if(!response.ok)throw new Error(payload.error||'History could not be loaded.');historyStorage.textContent='Storage: '+payload.storageDirectory;renderHistoryList(payload.runs);}catch(error){historyList.replaceChildren(el('div','history-empty',error.message));}}
    async function openHistoryRun(id){const response=await fetch('/api/history/'+id);const payload=await response.json();if(!response.ok){historyList.prepend(el('p','status error',payload.error||'Saved run could not be opened.'));return;}const result=payload.run.result;result.history={run:payload.run,comparison:payload.comparison,runs:payload.runs};historyDialog.close();render(result);status.className='status';status.textContent='Opened saved scan from '+new Date(result.metadata.completedAt).toLocaleString()+'.';}
    async function removeHistoryRun(run){if(!window.confirm('Delete the saved scan from '+new Date(run.completedAt).toLocaleString()+'? This removes its report, screenshots, manual progress, and notes from this computer.'))return;const response=await fetch('/api/history/'+run.id,{method:'DELETE'});const payload=await response.json();if(!response.ok){historyList.prepend(el('p','status error',payload.error||'Saved run could not be deleted.'));return;}if(currentRunId===run.id){currentRunId=null;currentComparison=null;runReview.hidden=true;}await loadHistory();}
    function enhanceRemediationGuidance(f){if(!f||!f.remediationGuidance)return;const sections=[...detail.querySelectorAll('.detail-section')];const fix=sections.find(section=>section.querySelector('h4')?.textContent==='Recommended fix');if(fix){fix.replaceChildren(el('h4','','Recommended fix'));fix.append(remediationStart(f));const grid=el('div','remediation-grid');grid.append(remediationCard('What to inspect',f.remediationGuidance.inspect));grid.append(remediationCard('What to change',f.remediationGuidance.change));fix.append(grid);if(f.safeFix)fix.append(el('p','review-note','Safe automated fix available: '+f.safeFix.description));}const codeSection=sections.find(section=>section.querySelector('h4')?.textContent==='Suggested change');const codeNote=codeSection?.querySelector('.review-note');if(codeNote&&f.codeSuggestion){codeNote.replaceChildren(document.createTextNode(f.codeSuggestion.reviewRequired?'Review required: ':''));appendTechnicalText(codeNote,f.codeSuggestion.rationale);codeSection.querySelectorAll('.alternative-list li').forEach((row,index)=>{row.replaceChildren();appendTechnicalText(row,f.codeSuggestion.alternatives[index]);});}const verify=sections.find(section=>section.querySelector('h4')?.textContent==='How to verify the fix');const steps=verify?.querySelector('.verify-list');if(steps){steps.replaceChildren();f.remediationGuidance.verify.forEach(item=>{const row=el('li','');appendTechnicalText(row,item);steps.append(row);});}}
